<main class="container section"><header class="archive-head"><span class="eyebrow">SEARCH</span><h1>搜尋店家</h1><p>「<?php echo esc_html($query); ?>」<?php echo $count?'共找到 '.$count.' 間店家。':'目前沒有符合的店家。'; ?></p></header>
